package com.company.workflowbuilder.entity.data;
import com.company.workflowbuilder.entity.user.User; import com.company.workflowbuilder.entity.workflow.Workflow; import jakarta.persistence.*; import lombok.*; import org.hibernate.annotations.CreationTimestamp; import org.hibernate.annotations.UpdateTimestamp; import java.time.LocalDateTime; import java.util.UUID;
@Entity @Table(name="workflow_data_bindings") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class WorkflowDataBinding { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="dataset_id",nullable=false) private Dataset dataset; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="workflow_id",nullable=false) private Workflow workflow; @Column(name="trigger_mode",nullable=false) @Builder.Default private String triggerMode="AUTO_ON_DATASET_SUCCESS"; @Column(name="filter_json",nullable=false,columnDefinition="TEXT") @Builder.Default private String filterJson="[]"; @Column(name="mapping_json",nullable=false,columnDefinition="TEXT") @Builder.Default private String mappingJson="{}"; @Column(name="last_consumed_version",nullable=false) private int lastConsumedVersion; @Column(nullable=false) @Builder.Default private boolean active=true; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="created_by",nullable=false) private User createdBy; @CreationTimestamp @Column(name="created_at",nullable=false,updatable=false) private LocalDateTime createdAt; @UpdateTimestamp @Column(name="updated_at",nullable=false) private LocalDateTime updatedAt; }
